// Initial zoom — nodes cluster around (0,0) so translate origin to screen center
svg.call(zoom.transform, d3.zoomIdentity.translate(W()/2, H()/2).scale(0.75));

// Once the simulation cools, fit the actual bounding box to the viewport
simulation.on('end', () => {
  const pad = 60;
  const xs = nodes.map(d => d.x), ys = nodes.map(d => d.y);
  const x0 = Math.min(...xs) - pad, x1 = Math.max(...xs) + pad;
  const y0 = Math.min(...ys) - pad, y1 = Math.max(...ys) + pad;
  const w = W(), h = H();
  const scale = Math.min(w / (x1 - x0), h / (y1 - y0), 1.2);
  const cx = (x0 + x1) / 2, cy = (y0 + y1) / 2;
  svg.transition().duration(800).ease(d3.easeCubicInOut).call(
    zoom.transform,
    d3.zoomIdentity.translate(w / 2, h / 2).scale(scale).translate(-cx, -cy)
  );
});

