let _ptrDown = null;
svg.on('pointerdown', e => { _ptrDown = [e.clientX, e.clientY]; })
   .on('click', e => {
     if (_ptrDown) {
       const d = Math.hypot(e.clientX - _ptrDown[0], e.clientY - _ptrDown[1]);
       if (d > 4) return; // was a pan, ignore
     }
     selectNode(null);
   });

